<?php require __DIR__.'/partials/header.php';$status=$_GET['stato']??'';$venue=$_GET['campo']??'';$month=$_GET['mese']??'';$sql='SELECT m.*,t.name opponent FROM matches m JOIN teams t ON t.id=m.opponent_id WHERE 1';$a=[];if($status!==''){$sql.=' AND m.status=?';$a[]=$status;}if($venue!==''){$sql.=' AND m.is_home=?';$a[]=(int)$venue;}if($month!==''){$sql.=' AND DATE_FORMAT(m.match_date,"%Y-%m")=?';$a[]=$month;}$sql.=' ORDER BY m.match_date';$q=$db->prepare($sql);$q->execute($a);$rows=$q->fetchAll();?><section class="page-hero"><div class="wrap"><span class="eyebrow">STAGIONE 2026 / 2027</span><h1>IL <em>CALENDARIO</em></h1><p>Partite, risultati e appuntamenti della stagione dimostrativa.</p></div></section><section class="wrap section"><form class="filters"><input type="month" name="mese" value="<?= e($month) ?>"><select name="campo"><option value="">Casa e trasferta</option><option value="1" <?= $venue==='1'?'selected':'' ?>>Casa</option><option value="0" <?= $venue==='0'?'selected':'' ?>>Trasferta</option></select><select name="stato"><option value="">Tutti gli stati</option><?php foreach(['programmata','in_corso','terminata','rinviata'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= e(ucfirst(str_replace('_',' ',$s))) ?></option><?php endforeach; ?></select><button class="btn btn-red">Applica</button></form><div class="match-list"><?php foreach($rows as $m): ?><article class="schedule-card"><div class="schedule-date"><b><?= date('d',strtotime($m['match_date'])) ?></b><span><?= strtoupper(date('M',strtotime($m['match_date']))) ?></span><small><?= date('H:i',strtotime($m['match_date'])) ?></small></div><div class="schedule-main"><span class="eyebrow"><?= $m['is_home']?'IN CASA':'IN TRASFERTA' ?> · <?= e($m['status']) ?></span><h3>Bartoli Mechanics <i>vs</i> <?= e($m['opponent']) ?></h3><p><?= e($m['venue']) ?></p></div><div class="schedule-score"><?php if($m['status']==='terminata'): ?><b><?= $m['is_home']?(int)$m['home_score']:(int)$m['away_score'] ?> - <?= $m['is_home']?(int)$m['away_score']:(int)$m['home_score'] ?></b><?php else: ?><a href="biglietti.php">Biglietti ↗</a><?php endif; ?></div></article><?php endforeach; ?></div><?php if(!$rows): ?><p class="empty">Nessuna partita corrisponde ai filtri.</p><?php endif; ?></section><?php require __DIR__.'/partials/footer.php'; ?>